def lis_tails(a):
    tails, owners, parent = [], [], [-1] * len(a)
    for i, x in enumerate(a):
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] >= x:
                hi = mid
            else:
                lo = mid + 1
        parent[i] = owners[lo - 1] if lo else -1
        if lo == len(tails):
            tails.append(x)
            owners.append(i)
        else:
            tails[lo] = x
            owners[lo] = i
    seq, i = [], owners[-1]
    while i != -1:
        seq.append(a[i])
        i = parent[i]
    seq.reverse()
    return len(tails), seq

def _brute_lis(a):
    best = 0
    for mask in range(1, 1 << len(a)):
        prev, length, ok = -10**18, 0, True
        for i, x in enumerate(a):
            if mask >> i & 1:
                if x <= prev:
                    ok = False
                    break
                prev, length = x, length + 1
        if ok:
            best = max(best, length)
    return best

