def nlis_memo(a):
    memo = [None] * len(a)

    def f(i):
        if memo[i] is None:
            length, count = 1, 1
            for j in range(i):
                if a[j] < a[i]:
                    lj, cj = f(j)
                    if lj + 1 > length:
                        length, count = lj + 1, cj
                    elif lj + 1 == length:
                        count += cj
            memo[i] = (length, count)
        return memo[i]

    pairs = [f(i) for i in range(len(a))]
    best = max(p[0] for p in pairs)
    return sum(p[1] for p in pairs if p[0] == best)
