def _dolls(env):
    return sorted(env, key=lambda e: (e[0], -e[1]))

def doll_rec(env):
    h = [e[1] for e in _dolls(env)]

    def f(i):
        best = 1
        for j in range(i):
            if h[j] < h[i]:
                best = max(best, 1 + f(j))
        return best

    return max(f(i) for i in range(len(h)))
