    def qry(lo, hi):
        if lo > hi:
            return 0
        ans, lo, hi = 0, lo + size, hi + size
        while lo <= hi:
            if lo & 1:
                ans = max(ans, tree[lo])
                lo += 1
            if not hi & 1:
                ans = max(ans, tree[hi])
                hi -= 1
            lo //= 2
            hi //= 2
        return ans

    def upd(i, val):
        i += size
        tree[i] = max(tree[i], val)
        i //= 2
        while i:
            tree[i] = max(tree[2 * i], tree[2 * i + 1])
            i //= 2

    ans = 1
    for x in a:
        got = qry(max(1, x - k), x - 1) + 1
        upd(x, got)
        ans = max(ans, got)
    return ans

