``` {.python .cell-code}
def dist_rec(s):
    found = set()

    def f(i, cur):
        if i == len(s):
            if cur:
                found.add(cur)
            return
        f(i + 1, cur)
        f(i + 1, cur + s[i])

    f(0, "")
    return len(found)
```
:::


##### C++

```cpp
void distWalk(int i, string cur, const string& s, set<string>& found) {
    if (i == (int)s.size()) {
        if (!cur.empty()) found.insert(cur);
        return;
    }
    distWalk(i + 1, cur, s, found);
    distWalk(i + 1, cur + s[i], s, found);
}
```
