``` {.python .cell-code}
def dist_memo(s):
    end = {}
    total = 1
    for ch in s:
        old = end.get(ch, 0)
        end[ch] = total
        total = (total + end[ch] - old) % MOD
    return (total - 1) % MOD
```
:::


##### C++

```cpp
int distMemo(const string& s) {
    const int MOD = 1000000007;
    long long end[26] = {}, total = 1;
    for (char ch : s) {
        int c = ch - 'a';
        long long old = end[c];
        end[c] = total;
        total = (total + end[c] - old + MOD) % MOD;
    }
    return (total - 1 + MOD) % MOD;
}
```
:::

